# Sync backend/.env from contracts deployment manifest (generated by DeployAllDemo).
param(
    [string]$RepoRoot = (Resolve-Path (Join-Path $PSScriptRoot "..")).Path,
    [ValidateSet("anvil-local", "anvil-fork-monad", "monad-testnet")]
    [string]$Profile = "anvil-local",
    [switch]$Hybrid,
    [string]$DeploymentFile = "",
    [string]$RpcUrl = "",
    [string]$AnvilPrivateKey = "0xac0974bec39a17e36ba4a6b4d238ff944bacb478cbed5efcae784d7bf4f2ff80"
)

$ErrorActionPreference = "Stop"

function Get-DemoChainProfile {
    param([string]$Name, [string]$Root)
    $profilesPath = Join-Path $Root "shared\demo-chain-profiles.json"
    if (-not (Test-Path $profilesPath)) {
        throw "Demo chain profiles not found: $profilesPath"
    }
    $profiles = Get-Content $profilesPath -Raw | ConvertFrom-Json
    $profile = $profiles.$Name
    if (-not $profile) {
        throw "Unknown DEMO profile '$Name' in $profilesPath"
    }
    return $profile
}

$chainProfile = Get-DemoChainProfile -Name $Profile -Root $RepoRoot
$anvilProfile = Get-DemoChainProfile -Name "anvil-local" -Root $RepoRoot
$anvilManifest = Join-Path $RepoRoot ($anvilProfile.manifestPath -replace "/", "\")

if (-not $DeploymentFile) {
    $DeploymentFile = Join-Path $RepoRoot ($chainProfile.manifestPath -replace "/", "\")
}

if (-not (Test-Path $DeploymentFile)) {
    throw "Deployment manifest not found: $DeploymentFile`nRun DeployAllDemo first."
}

$deployment = Get-Content $DeploymentFile -Raw | ConvertFrom-Json

$required = @("registry", "vaultExecution", "swapRouter", "scenarioDeployer")
foreach ($key in $required) {
    if (-not $deployment.$key) {
        throw "Deployment manifest missing '$key' in $DeploymentFile"
    }
}

$envPath = Join-Path $RepoRoot "backend\.env"
$deploymentPathRel = "..\contracts\deployments\" + (Split-Path $DeploymentFile -Leaf)

if (-not $RpcUrl) {
    if ($deployment.deploymentTarget -eq "remote" -or $Profile -eq "monad-testnet") {
        $RpcUrl = if ($env:MONAD_RPC_URL) { $env:MONAD_RPC_URL } else { $chainProfile.rpcUrl }
    } else {
        $RpcUrl = $chainProfile.rpcUrl
    }
}

$lines = @(
    "# Auto-generated by scripts/sync-backend-env.ps1 — $(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')",
    "CHAIN_MODE=demo",
    "DEMO_PROFILE=$Profile",
    "RPC_URL=$RpcUrl",
    "PORT=8080",
    "",
    "DEMO_DEPLOYMENT_PATH=$deploymentPathRel",
    "DEMO_REGISTRY_ADDRESS=$($deployment.registry)",
    "VAULT_EXECUTION_ADDRESS=$($deployment.vaultExecution)",
    "DEMO_SWAP_ROUTER_ADDRESS=$($deployment.swapRouter)",
    "DEMO_SCENARIO_DEPLOYER=$($deployment.scenarioDeployer)"
)
if ($deployment.ledger) {
    $lines += "DEMO_LEDGER_ADDRESS=$($deployment.ledger)"
}
if ($Hybrid) {
    if (-not (Test-Path $anvilManifest)) {
        throw "Hybrid mode requires Anvil manifest: $anvilManifest"
    }
    $anvilDeployment = Get-Content $anvilManifest -Raw | ConvertFrom-Json
    if (-not $anvilDeployment.ledger) {
        throw "Anvil manifest missing ledger — run DeployAllDemo on Anvil first"
    }
    $lines += "DEMO_HYBRID_MODE=true"
    $lines += "LEDGER_RPC_URL=http://127.0.0.1:8545"
    $lines += "LEDGER_DEPLOYMENT_PATH=..\contracts\deployments\local-31337-demo.json"
    $lines += "DEMO_LEDGER_ADDRESS=$($anvilDeployment.ledger)"
    $lines += "SENTINEL_LEDGER_SOURCE=chain"
    $lines += "LEDGER_MIRROR_TO_CHAIN=true"
    $lines += "LEDGER_MIRROR_PRIVATE_KEY=$AnvilPrivateKey"
    $lines += "POOL_VOLUME_SOURCE=anvil-ledger"
    $lines += "LEDGER_BOOTSTRAP_ON_START=false"
    $lines += "LEDGER_SEED_ON_START=false"
}
elseif ($deployment.ledger -and ($Profile -eq "monad-testnet" -or $deployment.deploymentTarget -eq "remote")) {
    $lines += "SENTINEL_LEDGER_SOURCE=chain"
    $lines += "POOL_VOLUME_SOURCE=chain"
    $lines += "LEDGER_BOOTSTRAP_ON_START=false"
    $lines += "LEDGER_MIRROR_TO_CHAIN=false"
}
elseif ($deployment.achievements) {
    $lines += "DEMO_ACHIEVEMENTS_ADDRESS=$($deployment.achievements)"
}

$isLocal = ($chainProfile.deploymentTarget -eq "local") -or ($deployment.deploymentTarget -eq "local")

# Local Anvil full stack — read chain ledger when deployed
if (-not $Hybrid -and $isLocal -and $deployment.ledger) {
    $lines += "SENTINEL_LEDGER_SOURCE=chain"
    $lines += "POOL_VOLUME_SOURCE=ledger"
    $lines += "LEDGER_BOOTSTRAP_ON_START=false"
}
# Local Anvil without on-chain ledger
elseif (-not $Hybrid -and $isLocal) {
    $lines += "SENTINEL_LEDGER_SOURCE=local"
    $lines += "POOL_VOLUME_SOURCE=ledger"
    $lines += "LEDGER_BOOTSTRAP_ON_START=false"
}
if ($env:DATABASE_URL) {
    $lines += "DATABASE_URL=$($env:DATABASE_URL)"
}
$lines += ""

if ($isLocal) {
    $lines += @(
        "# Anvil account #0 (deployer + agentSigner by default)",
        "SWAP_PRIVATE_KEY=$AnvilPrivateKey",
        "EXECUTOR_PRIVATE_KEY=$AnvilPrivateKey",
        "AGENT_PRIVATE_KEY=$AnvilPrivateKey",
        ""
    )
} else {
    $agentKey = ""
    $contractsEnv = Join-Path $RepoRoot "contracts\.env"
    if (Test-Path $contractsEnv) {
        Get-Content $contractsEnv | ForEach-Object {
            $line = $_.Trim()
            if ($line -match '^PRIVATE_KEY=(.+)$') {
                $agentKey = $Matches[1].Trim().Trim('"').Trim("'")
            }
        }
    }
    if ($agentKey) {
        $lines += @(
            "# Remote — backend Agent signs permits; user swaps via MetaMask",
            "SWAP_PRIVATE_KEY=",
            "EXECUTOR_PRIVATE_KEY=",
            "AGENT_PRIVATE_KEY=$agentKey",
            ""
        )
    } else {
        $lines += @(
            "# Remote — set AGENT_PRIVATE_KEY for Safe MetaMask swap (Agent EIP-712 signing)",
            "SWAP_PRIVATE_KEY=",
            "EXECUTOR_PRIVATE_KEY=",
            "AGENT_PRIVATE_KEY=",
            ""
        )
    }
}

Set-Content -Path $envPath -Value ($lines -join "`n") -Encoding ASCII

Write-Host "Wrote backend/.env from deployment manifest:"
Write-Host "  profile        = $Profile"
Write-Host "  rpcUrl         = $RpcUrl"
Write-Host "  registry       = $($deployment.registry)"
Write-Host "  vault          = $($deployment.vaultExecution)"
Write-Host "  swapRouter     = $($deployment.swapRouter)"
Write-Host "  scenarioDeployer = $($deployment.scenarioDeployer)"
if ($deployment.ledger) {
    Write-Host "  ledger         = $($deployment.ledger)"
}

return @{
    EnvPath = $envPath
    Deployment = $deployment
    Profile = $chainProfile
}
